package com.celik.kingdoms;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.celik.kingdoms.AirDropRules.*;
import java.util.*;

class AirDropRulesTest {
    Drop d;String a,b,solo;long now;
    @BeforeEach void setup(){d=new Drop();d.dimension="minecraft:overworld";d.createdAt=1000;d.landsAt=2000;d.expiresAt=1000000;d.startY=184;d.y=64;d.captureRadius=15;d.verticalRadius=3;d.requiredMembers=3;d.captureMillis=90000;d.graceMillis=15000;d.soloMultiplier=1.5;d.interferenceMultiplier=1.3;d.phase=Phase.CAPTURABLE;a=kingdom(UUID.randomUUID());b=kingdom(UUID.randomUUID());solo=solo(UUID.randomUUID());now=100000;}
    String step(Map<String,Integer> counts,long elapsed){now+=elapsed;return advance(d,counts,elapsed,now);}
    @Test void defaultsMatchApprovedSchedule(){AirDropConfig c=new AirDropConfig();c.validate();assertEquals(180,c.intervalMinutes);assertEquals(20,c.jitterMinutes);assertEquals(600,c.descentSeconds);assertEquals(15,c.captureRadius);assertEquals(0,c.claimBufferBlocks);assertEquals(5,c.protectionRadius);assertEquals(3,c.captureVerticalRadius);assertEquals(3,c.soloControlStrength);assertEquals(3,c.kingdomMembers);}
    @Test void onlineThresholdBoundaries(){AirDropConfig c=new AirDropConfig();assertEquals(0,c.dropsFor(9));assertEquals(1,c.dropsFor(10));assertEquals(1,c.dropsFor(19));assertEquals(2,c.dropsFor(20));c.playerThresholds.put(50,3);assertEquals(3,c.dropsFor(50));}
    @Test void ageUsesRealTwentyFourHourDays(){long epoch=100000;assertEquals(1,day(epoch,epoch));assertEquals(1,day(epoch,epoch+86399999));assertEquals(2,day(epoch,epoch+86400000));assertEquals(7,day(epoch,epoch+6*86400000L));assertEquals(1,day(epoch,epoch-1));}
    @Test void tiersUnlockOnDaysOneThreeFiveSeven(){AirDropConfig c=new AirDropConfig();for(int day=1;day<=12;day++)assertEquals(day<3?1:day<5?3:day<7?5:7,c.tier(day).fromDay);}
    @Test void eightVariantWeightsMatchDocument(){AirDropConfig c=new AirDropConfig();assertArrayEquals(new int[]{6000,1200,1000,700,500,400,180,20},c.variants.stream().mapToInt(v->v.weight).toArray());assertEquals(10000,c.variants.stream().mapToInt(v->v.weight).sum());}
    @Test void rareChancesArePerTier(){AirDropConfig c=new AirDropConfig();var r=c.rareRewards.stream().filter(x->x.key.equals("elytra")).findFirst().orElseThrow();assertEquals(0,r.chance(6));assertEquals(.005,r.chance(7));assertEquals(.005,r.chance(100));}
    @Test void unsafeConfigurationRejected(){AirDropConfig c=new AirDropConfig();c.nearbyRadius=14;assertThrows(IllegalArgumentException.class,c::validate);c=new AirDropConfig();c.variants.getLast().rarityMultiplier=5.01;assertThrows(IllegalArgumentException.class,c::validate);c=new AirDropConfig();c.rareRewards.getFirst().chanceByDay.put(1,1.1);assertThrows(IllegalArgumentException.class,c::validate);}
    @Test void quorumRequired(){assertNull(step(Map.of(a,2),90000));assertTrue(d.progress.isEmpty());assertTrue(quorum(d,a,3));assertTrue(quorum(d,solo,1));}
    @Test void kingdomWinsAfterNinetySeconds(){assertNull(step(Map.of(a,3),89999));assertEquals(a,step(Map.of(a,3),1));}
    @Test void extraMembersDoNotSpeedCapture(){step(Map.of(a,12),45000);assertEquals(45000,d.progress.get(a).millis);}
    @Test void soloNeedsOneHundredThirtyFiveSeconds(){assertNull(step(Map.of(solo,1),134999));assertEquals(solo,step(Map.of(solo,1),1));}
    @Test void soloHasStrengthThreeAndLargerKingdomStartsFresh(){step(Map.of(solo,1),45000);step(Map.of(solo,1,a,3),13000);assertEquals(solo,d.capturingSide);assertEquals(55000,d.progress.get(solo).millis);step(Map.of(solo,1,a,4),1000);assertEquals(solo,d.capturingSide);step(Map.of(solo,1,a,4),15000);assertEquals(a,d.capturingSide);assertEquals(0,d.progress.get(a).millis);assertFalse(d.progress.containsKey(solo));}
    @Test void gracePausesProgress(){step(Map.of(a,3),30000);step(Map.of(a,2),1000);long missing=d.progress.get(a).missingSince;step(Map.of(a,2),14999);assertEquals(30000,d.progress.get(a).millis);assertEquals(missing,d.progress.get(a).missingSince);}
    @Test void restoringQuorumResumesWithoutAwardingPausedTime(){step(Map.of(a,3),30000);step(Map.of(a,2),1000);step(Map.of(a,3),5000);assertEquals(30000,d.progress.get(a).millis);step(Map.of(a,3),1000);assertEquals(31000,d.progress.get(a).millis);assertEquals(0,d.progress.get(a).missingSince);}
    @Test void graceExpiresAtExactDeadline(){step(Map.of(a,3),30000);step(Map.of(),1000);step(Map.of(),15000);assertTrue(d.progress.isEmpty());assertNull(d.capturingSide);}
    @Test void returningAfterGraceStartsFromZero(){step(Map.of(a,3),30000);step(Map.of(),1000);step(Map.of(a,3),16000);assertEquals(0,d.progress.get(a).millis);step(Map.of(a,3),1000);assertEquals(1000,d.progress.get(a).millis);}
    @Test void zeroGraceResetsImmediately(){d.graceMillis=0;step(Map.of(a,3),10000);step(Map.of(),1);assertTrue(d.progress.isEmpty());assertNull(d.capturingSide);}
    @Test void oneRivalSlowsWithoutQuorum(){step(Map.of(a,3,b,1),13000);assertEquals(10000,d.progress.get(a).millis,1e-7);assertFalse(d.progress.containsKey(b));assertTrue(d.progress.get(a).contested);}
    @Test void interferenceDoesNotStack(){step(Map.of(a,12,b,10,solo,1),13000);assertEquals(10000,d.progress.get(a).millis,1e-7);}
    @Test void onlyOneSideProgressesAndTiesPreserveControl(){step(Map.of(a,3),10000);step(Map.of(a,3,b,3),13000);assertEquals(a,d.capturingSide);assertEquals(20000,d.progress.get(a).millis,1e-7);assertFalse(d.progress.containsKey(b));}
    @Test void largerQualifiedSideTakesOverAfterFifteenSeconds(){step(Map.of(a,3),50000);step(Map.of(a,3,b,4),1000);assertEquals(a,d.capturingSide);assertEquals(50000,d.progress.get(a).millis);step(Map.of(a,3,b,4),14999);assertEquals(a,d.capturingSide);step(Map.of(a,3,b,4),1);assertEquals(b,d.capturingSide);assertEquals(0,d.progress.get(b).millis);assertFalse(d.progress.containsKey(a));step(Map.of(a,3,b,4),13000);assertEquals(10000,d.progress.get(b).millis,1e-7);}
    @Test void unqualifiedGroupCannotTakeControl(){step(Map.of(solo,1),45000);step(Map.of(solo,1,a,2),13000);assertEquals(solo,d.capturingSide);assertEquals(55000,d.progress.get(solo).millis,1e-7);}
    @Test void disablingTakeoverRetainsHolderUntilGraceExpires(){d.largerGroupTakeover=false;step(Map.of(a,3),10000);step(Map.of(a,3,b,10),13000);assertEquals(a,d.capturingSide);step(Map.of(b,10),1000);step(Map.of(b,10),15000);assertEquals(b,d.capturingSide);assertEquals(0,d.progress.get(b).millis);}
    @Test void rivalLeavingRestoresNormalSpeed(){step(Map.of(a,3,b,1),13000);step(Map.of(a,3),10000);assertEquals(20000,d.progress.get(a).millis,1e-7);assertFalse(d.progress.get(a).contested);}
    @Test void contestedSoloUsesBothMultipliers(){assertNull(step(Map.of(solo,1,b,1),175499));assertEquals(solo,step(Map.of(solo,1,b,1),1));}
    @Test void earliestCompletionWithinSampleWins(){step(Map.of(a,3),89000);assertEquals(a,step(Map.of(a,3,solo,1),2000));assertFalse(d.progress.containsKey(solo));}
    @Test void tiesDoNotDependOnMapInsertionOrder(){Drop copy=Store.JSON.fromJson(Store.JSON.toJson(d),Drop.class);var first=new LinkedHashMap<String,Integer>();first.put(a,3);first.put(b,3);var reverse=new LinkedHashMap<String,Integer>();reverse.put(b,3);reverse.put(a,3);assertEquals(advance(d,first,117000,now),advance(copy,reverse,117000,now));}
    @Test void negativeElapsedCannotAdvance(){step(Map.of(a,3),-1);assertEquals(0,d.progress.get(a).millis);}
    @Test void descentAndTerminalStatesCannotCapture(){for(Phase p:List.of(Phase.DESCENDING,Phase.CLAIMED,Phase.CANCELLED,Phase.EXPIRED)){d.phase=p;assertNull(step(Map.of(a,3),90000));assertTrue(d.progress.isEmpty());}}
    @Test void controlledDescentIsClamped(){assertEquals(184,d.height(0));assertEquals(124,d.height(1500));assertEquals(64,d.height(3000));}
    @Test void configurableBuildRadiusHasExactBoundary(){assertTrue(d.protectsBlock(0,64,0));assertTrue(d.protectsBlock(5,64,0));assertTrue(d.protectsBlock(5,300,0));assertFalse(d.protectsBlock(6,64,0));assertFalse(d.protectsBlock(4,64,4));d.phase=Phase.CLAIMED;assertFalse(d.protectsBlock(0,64,0));}
    @Test void zeroBuildRadiusOnlyReservesLandingAndSupport(){d.protectionRadius=0;assertTrue(d.protectsBlock(0,64,0));assertTrue(d.protectsBlock(0,63,0));assertFalse(d.protectsBlock(1,64,0));assertFalse(d.protectsBlock(0,65,0));}
    @Test void claimReservationUsesCaptureRadius(){assertTrue(d.withinCaptureArea(.5,.5));assertTrue(d.withinCaptureArea(15.5,.5));assertFalse(d.withinCaptureArea(15.51,.5));d.phase=Phase.CLAIMED;assertFalse(d.withinCaptureArea(.5,.5));}
    @Test void previousDefaultsUpgradeToNewRadiusAndHeight(){AirDropConfig c=Store.JSON.fromJson("{\"protectionRadius\":25,\"maxSlope\":3,\"captureRadius\":15}",AirDropConfig.class);c.validate();assertEquals(5,c.protectionRadius);assertFalse(Store.JSON.toJson(c).contains("maxSlope"));assertEquals(512,c.candidateAttempts);}
    @Test void explicitNewSettingsStayCustomizable(){AirDropConfig c=new AirDropConfig();c.validate();c.protectionRadius=25;c.captureVerticalRadius=6;c.validate();assertEquals(25,c.protectionRadius);assertEquals(6,c.captureVerticalRadius);}
    @Test void legacyDropSnapshotsUpgradeOnlyOldDefaults(){d.verticalRadius=6;d.protectionRadius=25;normalizeCapture(d);assertEquals(3,d.verticalRadius);assertEquals(5,d.protectionRadius);d.verticalRadius=6;d.protectionRadius=25;normalizeCapture(d);assertEquals(6,d.verticalRadius);assertEquals(25,d.protectionRadius);}
    @Test void legacyIndependentTimersKeepOnlyMostAdvancedSide(){Progress first=new Progress(),second=new Progress();first.millis=10000;second.millis=50000;d.progress.put(a,first);d.progress.put(b,second);normalizeCapture(d);assertEquals(b,d.capturingSide);assertEquals(Set.of(b),d.progress.keySet());}
    @Test void captureRadiusAndProtectionCanBeDifferent(){AirDropConfig c=new AirDropConfig();c.captureRadius=22;c.protectionRadius=2;c.captureVerticalRadius=0;c.validate();assertEquals(2,c.protectionRadius);c.dustSize=Float.NaN;assertThrows(IllegalArgumentException.class,c::validate);}
    @Test void savedProgressAndLootIdsSurviveSerialization(){step(Map.of(a,3),45000);step(Map.of(),1000);Reward r=new Reward();r.itemJson="test";d.loot.add(r);Data data=new Data();data.drops.add(d);validate(data);Data restored=Store.JSON.fromJson(Store.JSON.toJson(data),Data.class);validate(restored);assertEquals(45000,restored.drops.getFirst().progress.get(a).millis);assertEquals(r.id,restored.drops.getFirst().loot.getFirst().id);}
    @Test void duplicateRewardOrInvalidProgressFailsClosed(){Reward r=new Reward();r.itemJson="test";d.loot.add(r);d.loot.add(r);Data data=new Data();data.drops.add(d);assertThrows(IllegalStateException.class,()->validate(data));d.loot.clear();Progress p=new Progress();p.millis=Double.NaN;d.progress.put(a,p);assertThrows(IllegalStateException.class,()->validate(data));}
    @Test void pendingLootRequiresReceiver(){Reward r=new Reward();r.itemJson="test";r.status=LootStatus.PENDING;d.loot.add(r);Data data=new Data();data.drops.add(d);assertThrows(IllegalStateException.class,()->validate(data));r.receiver=UUID.randomUUID();validate(data);}
    @Test void challengerLosingLeadCancelsTakeoverWithoutCreditingPause(){step(Map.of(a,3),10000);step(Map.of(a,3,b,4),1000);step(Map.of(a,3,b,4),14000);step(Map.of(a,3,b,3),1000);assertEquals(a,d.capturingSide);assertNull(d.takeoverSide);assertEquals(10000,d.progress.get(a).millis);step(Map.of(a,3,b,4),1000);step(Map.of(a,3,b,4),14000);assertEquals(a,d.capturingSide);step(Map.of(a,3,b,4),1000);assertEquals(b,d.capturingSide);}
    @Test void shuffledLayoutSurvivesRestartAndCollection(){var before=chestSlots(d,0,27);assertEquals(27,new HashSet<>(before).size());assertNotEquals(java.util.stream.IntStream.range(0,27).boxed().toList(),before);var loaded=Store.JSON.fromJson(Store.JSON.toJson(d),Drop.class);assertEquals(before,chestSlots(loaded,0,27));assertNotEquals(before,chestSlots(d,1,27));}
    @Test void paginationNeverUsesNavigationSlots(){assertTrue(chestSlots(d,0,24).stream().allMatch(n->n<24));}
}
